class Solution {
public:
    int subarraySum(vector<int>& nums, int k) {
        unordered_map<int, int> freq;
        freq[0] = 1;
        int prefix = 0, count = 0;
        for (int x : nums) {
            prefix += x;
            count += freq[prefix - k];
            freq[prefix]++;
        }
        return count;
    }
};

